const $=s=>document.querySelector(s);
let lang=document.documentElement.lang==='ar'?'ar':'en',brand='all',selected,detailProduct,photoIndex=0;

const requestedLang=new URLSearchParams(location.search).get('lang');if(['en','ar'].includes(requestedLang))lang=requestedLang;
const t=key=>translations[lang][key]||translations.en[key]||key;
const money=n=>'$'+n.toLocaleString('en-US');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function localSpec(s){if(lang!=='ar')return s;return s.replaceAll('Integrated graphics',t('integrated')).replaceAll('Silver',t('silver')).replaceAll('Grey',t('grey')).replaceAll('Black',t('black')).replaceAll('Original Lenovo bag included',t('bag')).replaceAll('Touch','لمس').replaceAll('15.6″','15.6 بوصة').replaceAll('15.3″','15.3 بوصة').replaceAll('16″','16 بوصة')}
const photos=p=>galleries[photoKeys[p.id]]||[{src:p.photo,view:'front'}];
const imageAlt=(p,photo)=>`${p.brand} ${p.name} ${p.model} — ${t(photo.view)}`;
const productNumber=p=>String(p.id+1).padStart(2,'0');
const numberBadge=p=>`<span class="product-number" dir="ltr" aria-label="${lang==='ar'?'رقم الجهاز':'Laptop number'} ${productNumber(p)}"><small>No.</small> ${productNumber(p)}</span>`;
const art=p=>`<button class="product-photo card-photo" data-detail="${p.id}" aria-label="${esc(p.name+' · '+t('details'))}"><img src="${photos(p)[0].src}" alt="${esc(imageAlt(p,photos(p)[0]))}" width="600" height="420" loading="lazy" decoding="async"><span class="photo-count">▧ ${photos(p).length} ${t('photos')}</span></button>`;
function render(){const query=$('#search').value.toLowerCase().trim();let list=products.filter(p=>(brand==='all'||p.brand===brand)&&[p.brand,p.name,p.model,p.cpu,p.ram,p.storage,p.display,p.gpu,p.extra,localSpec(p.extra),localSpec(p.gpu),p.price].join(' ').toLowerCase().includes(query));if($('#sort').value!=='featured')list.sort((a,b)=>$('#sort').value==='low'?a.price-b.price:b.price-a.price);$('#count').textContent=`${list.length} ${t('count')}`;$('#products').innerHTML=list.map(p=>`<article><div class="card-top">${numberBadge(p)}<span dir="ltr">${p.brand.toUpperCase()}</span><span class="badge">${t(p.gpu.includes('RTX')?'gaming':'everyday')}</span></div>${art(p)}<h3><bdi>${p.name}</bdi></h3><p class="model"><bdi>${p.model}</bdi></p><div class="specs"><span><bdi>${p.cpu}</bdi></span><span><bdi>${p.ram} · ${p.storage}</bdi></span><span><bdi>${localSpec(p.display)}</bdi></span><span><bdi>${localSpec(p.gpu)}</bdi></span></div><button class="detail-link" data-detail="${p.id}">${t('details')}</button><div class="card-bottom"><strong dir="ltr">${money(p.price)}<small> USD</small></strong><button class="buy" data-buy="${p.id}">${t('buy')}</button></div></article>`).join('')||`<p class="empty">${t('empty')}</p>`;}
function renderFilters(){$('#filters').innerHTML=['all','ASUS','HP','Lenovo','Dell','Acer','MSI'].map(b=>`<button class="filter ${brand===b?'active':''}" data-brand="${b}" aria-pressed="${brand===b}">${b==='all'?t('all'):b}</button>`).join('')}
function applyLanguage(next){lang=next==='ar'?'ar':'en';try{localStorage.setItem('laptop-house-language',lang)}catch{}document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.title=lang==='ar'?'لابتوب هاوس سوريا | أسعار وعروض اللابتوبات | Laptop House':'Laptop House Syria | Laptop Prices & Offers | لابتوب هاوس';document.querySelectorAll('[data-i18n]').forEach(el=>el.innerHTML=t(el.dataset.i18n));document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>el.placeholder=t(el.dataset.i18nPlaceholder));document.querySelectorAll('[data-i18n-aria]').forEach(el=>el.setAttribute('aria-label',t(el.dataset.i18nAria)));document.querySelectorAll('[data-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.lang===lang);b.setAttribute('aria-pressed',b.dataset.lang===lang)});renderFilters();render();if(detailProduct)renderDetails();if(selected)updateSummary();if($('#photo-viewer').open)updatePhoto();if(window.updateLaptopShowcase)window.updateLaptopShowcase()}
function updateSummary(){const p=selected;$('#order-summary').innerHTML=`<bdi>#${productNumber(p)} · ${p.brand} ${p.name} · ${p.model} · ${p.ram} · ${money(p.price)} USD</bdi>`}
function order(id){selected=products[id];$('#details').close();$('#order-form').reset();$('#wa-fallback').hidden=true;updateSummary();$('#order').showModal()}
function renderDetails(){const p=detailProduct;$('#detail-content').innerHTML=`${numberBadge(p)}<p class="eyebrow"><bdi>${p.brand}</bdi> / ${t('fullSpecs')}</p><h2><bdi>${p.name}</bdi></h2><p class="model"><bdi>${p.model}</bdi></p><div class="gallery-stage"><button class="gallery-arrow prev" data-gallery-step="-1" aria-label="${t('previous')}">‹</button><button class="enlarge-photo" data-zoom aria-label="${t('enlarge')}"><img id="gallery-main" width="700" height="480" alt=""></button><button class="gallery-arrow next" data-gallery-step="1" aria-label="${t('next')}">›</button><span class="enlarge-hint">⤢ ${t('enlarge')}</span></div><p id="gallery-caption" class="gallery-caption" aria-live="polite"></p><div class="gallery-thumbs" aria-label="${t('photos')}">${photos(p).map((ph,i)=>`<button data-gallery-index="${i}" aria-label="${t(ph.view)}"><img src="${ph.src}" alt="${esc(imageAlt(p,ph))}" loading="lazy"><span>${t(ph.view)}</span></button>`).join('')}</div><p class="photo-note">${t('reference')}</p><dl>${[['processor',p.cpu],['memory',p.ram],['storage',p.storage],['display',localSpec(p.display)],['graphics',localSpec(p.gpu)],['other',localSpec(p.extra)||t('notSpecified')]].map(([k,v])=>`<div><dt>${t(k)}</dt><dd><bdi>${v}</bdi></dd></div>`).join('')}</dl><div class="detail-price"><bdi dir="ltr">${money(p.price)} <small>USD</small></bdi></div><p class="privacy">${t('catalogNote')}</p><button class="primary" data-buy="${p.id}">${t('requestThis')}</button>`;updatePhoto()}
function updatePhoto(){if(!detailProduct)return;const items=photos(detailProduct);photoIndex=(photoIndex+items.length)%items.length;const ph=items[photoIndex],caption=`${t(ph.view)} · <bdi dir="ltr">${photoIndex+1} / ${items.length}</bdi>`;$('#gallery-main').src=ph.src;$('#gallery-main').alt=imageAlt(detailProduct,ph);$('#gallery-caption').innerHTML=caption;document.querySelectorAll('[data-gallery-index]').forEach((el,i)=>{el.classList.toggle('active',i===photoIndex);el.setAttribute('aria-pressed',i===photoIndex)});$('#zoom-image').src=ph.src;$('#zoom-image').alt=imageAlt(detailProduct,ph);$('#zoom-caption').innerHTML=caption}
$('#filters').onclick=e=>{const b=e.target.closest('[data-brand]');if(!b)return;brand=b.dataset.brand;renderFilters();render()};$('#search').oninput=render;$('#sort').onchange=render;
document.addEventListener('click',e=>{const b=e.target.closest('[data-buy]'),d=e.target.closest('[data-detail]'),l=e.target.closest('[data-lang]'),thumb=e.target.closest('[data-gallery-index]'),step=e.target.closest('[data-gallery-step],[data-photo-step]');if(l){location.href=l.dataset.lang==='ar'?'ar.html':'./';return;}if(b)order(+b.dataset.buy);if(d){detailProduct=products[+d.dataset.detail];photoIndex=0;renderDetails();$('#details').showModal()}if(thumb){photoIndex=+thumb.dataset.galleryIndex;updatePhoto()}if(step){photoIndex+=Number(step.dataset.galleryStep||step.dataset.photoStep);updatePhoto()}if(e.target.closest('[data-zoom]'))$('#photo-viewer').showModal();if(e.target.closest('.close'))e.target.closest('dialog').close()});
document.addEventListener('keydown',e=>{if(!$('#details').open&&!$('#photo-viewer').open)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();photoIndex+=(e.key==='ArrowRight'?1:-1);updatePhoto()}});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
$('#order-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),p=selected;const message=`${t('hello')}\n#${productNumber(p)} · ${p.brand} ${p.name} (${p.model})\n${p.cpu} | ${p.ram} | ${p.storage}\n${localSpec(p.gpu)} | ${localSpec(p.display)}\n${t('listedPrice')}: ${money(p.price)} USD\n\n${t('name')}: ${f.get('name').trim()}\n${t('phone')}: ${f.get('phone').trim()}\n${t('city')}: ${f.get('city').trim()}\n${t('address')}: ${f.get('address').trim()||t('toConfirm')}\n${t('notes')}: ${f.get('notes').trim()||t('none')}\n\n${t('confirmMessage')}`;const url='https://wa.me/963982759514?text='+encodeURIComponent(message);const a=$('#wa-fallback');a.href=url;a.hidden=false;window.open(url,'_blank','noopener,noreferrer')};applyLanguage(lang);
